package com.ykt.assistant;
import org.junit.Test;
import org.json.JSONObject;
import org.json.JSONArray;
import okhttp3.*;
import okio.Buffer;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;
public class AiClientTest {
    Response response(Request request,int code,String content){return new Response.Builder().request(request).protocol(Protocol.HTTP_1_1).code(code).message("test").body(ResponseBody.create(content,MediaType.get("application/json"))).build();}
    AiQuestion question()throws Exception{AiProtocolTest fixture=new AiProtocolTest();fixture.question(1);return fixture.snapshot;}
    String result(AiQuestion q)throws Exception{return RainApi.object("schema_version",1,"question_token",q.token,"problem_type",1,"status","answered","answer",RainApi.object("option_keys",new JSONArray().put("A"),"blank_values",new JSONArray(),"text",""),"explanation","理由","confidence",.9).toString();}
    String envelope(String content)throws Exception{return RainApi.object("choices",new JSONArray().put(RainApi.object("finish_reason","stop","message",RainApi.object("content",content)))).toString();}
    AiConfig config(boolean json,boolean image){return new AiConfig("https://ai.example/v1","model-name","local-test-key",json,image,false);}
    @Test public void isolatedRequestUsesJsonPromptAndOnlyProviderCredentials()throws Exception{AiQuestion q=question();AtomicInteger seen=new AtomicInteger();AiClient client=new AiClient(config(true,false),"Chosen-UA",new OkHttpClient.Builder().addInterceptor(chain->{Request r=chain.request();seen.incrementAndGet();assertEquals("Bearer local-test-key",r.header("Authorization"));assertEquals("Chosen-UA",r.header("User-Agent"));assertNull(r.header("Cookie"));assertNull(r.header("x-uid"));assertNull(r.header("sessionid"));assertTrue(r.body().isOneShot());Buffer buffer=new Buffer();r.body().writeTo(buffer);try{JSONObject body=new JSONObject(buffer.readUtf8());assertEquals("model-name",body.getString("model"));assertFalse(body.getBoolean("stream"));assertEquals("json_object",body.getJSONObject("response_format").getString("type"));assertEquals(AiQuestion.SYSTEM_PROMPT,body.getJSONArray("messages").getJSONObject(0).getString("content"));return response(r,200,envelope(result(q)));}catch(Exception e){throw new java.io.IOException(e);}}));assertTrue(client.analyze(q,null).answered());assertEquals(1,seen.get());client.close();}
    @Test public void imageIsInlineAndJsonModeAlwaysSent()throws Exception{AiQuestion q=question();AiClient client=new AiClient(config(false,true),"UA",new OkHttpClient.Builder().addInterceptor(chain->{Buffer buffer=new Buffer();chain.request().body().writeTo(buffer);try{JSONObject body=new JSONObject(buffer.readUtf8());assertEquals("json_object",body.getJSONObject("response_format").getString("type"));JSONArray content=body.getJSONArray("messages").getJSONObject(1).getJSONArray("content");assertTrue(content.getJSONObject(1).getJSONObject("image_url").getString("url").startsWith("data:image/jpeg;base64,"));return response(chain.request(),200,envelope(result(q)));}catch(Exception e){throw new java.io.IOException(e);}}));assertTrue(client.analyze(q,new byte[]{1,2,3}).answered());client.close();}
    @Test public void authAndProviderErrorsDoNotEchoSecretsOrRetry()throws Exception{for(int code:new int[]{401,403,429,503,302}){AtomicInteger count=new AtomicInteger();AiClient client=new AiClient(config(false,false),"UA",new OkHttpClient.Builder().addInterceptor(chain->{count.incrementAndGet();return response(chain.request(),code,"local-test-key provider secret");}));try{client.analyze(question(),null);fail();}catch(Exception e){assertFalse(e.getMessage().contains("local-test-key"));}assertEquals(1,count.get());client.close();}}
    @Test public void anonymousProviderOmitsAuthorizationHeader()throws Exception{AiQuestion q=question();AiClient client=new AiClient(new AiConfig("https://ai.example/v1","m","",false,false,false),"UA",new OkHttpClient.Builder().addInterceptor(chain->{assertNull(chain.request().header("Authorization"));try{return response(chain.request(),200,envelope(result(q)));}catch(Exception e){throw new java.io.IOException(e);}}));assertTrue(client.analyze(q,null).answered());client.close();}
    @Test public void malformedEnvelopeAndTruncationNeverProduceAnswer()throws Exception{for(String body:new String[]{"not json","{}","{\"choices\":[{\"finish_reason\":\"length\",\"message\":{\"content\":\"{}\"}}]}"}){AiClient client=new AiClient(config(false,false),"UA",new OkHttpClient.Builder().addInterceptor(chain->response(chain.request(),200,body)));try{client.analyze(question(),null);fail();}catch(Exception expected){}client.close();}}
    @Test public void closingClientCancelsInFlightRequest()throws Exception{CountDownLatch entered=new CountDownLatch(1);AiClient client=new AiClient(config(false,false),"UA",new OkHttpClient.Builder().addInterceptor(chain->{entered.countDown();while(!chain.call().isCanceled())try{Thread.sleep(5);}catch(InterruptedException e){Thread.currentThread().interrupt();break;}throw new java.io.IOException("cancelled");}));ExecutorService worker=Executors.newSingleThreadExecutor();try{Future<?> future=worker.submit(()->{try{client.analyze(question(),null);fail();}catch(Exception e){assertTrue(e.getMessage().contains("取消"));}});assertTrue(entered.await(3,TimeUnit.SECONDS));client.close();future.get(3,TimeUnit.SECONDS);}finally{client.close();worker.shutdownNow();}}
}
